public class LeastConnectionsLoadBalancer {
    private final List<ServerNode> servers;

    public LeastConnectionsLoadBalancer(List<ServerNode> servers) {
        this.servers = servers;
    }

    public ServerNode selectServer() {
        return servers.stream()
            .min(Comparator.comparingInt(ServerNode::getActiveConnections))
            .orElseThrow(() -> new IllegalStateException(
                "No active backend servers available"));
    }
}
